// Saniteer alle tekstinvoer: verwijder single quotes (SQL-escape) en trim
function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/'/g, "''").trim();
}

// Valideer numerieke waarden
function safeFloat(val, fallback) {
  const n = parseFloat(val);
  return isNaN(n) ? fallback : Math.abs(n);
}

// Valideer BTW percentage (mag alleen 0, 9 of 21 zijn)
function safeBtw(val) {
  const allowed = [0, 9, 21];
  const n = parseInt(val);
  return allowed.includes(n) ? n : 21;
}

const raw = $input.first().json.body || {};

return [{
  json: {
    klant:          sanitize(raw.klant),
    project:        sanitize(raw.project),
    omschrijving1:  sanitize(raw.omschrijving1),
    aantal1:        safeFloat(raw.aantal1, 1),
    prijs1:         safeFloat(raw.prijs1, 0),
    btw1:           safeBtw(raw.btw1),
    omschrijving2:  sanitize(raw.omschrijving2),
    aantal2:        safeFloat(raw.aantal2, 1),
    prijs2:         safeFloat(raw.prijs2, 0),
    btw2:           safeBtw(raw.btw2),
    omschrijving3:  sanitize(raw.omschrijving3),
    aantal3:        safeFloat(raw.aantal3, 1),
    prijs3:         safeFloat(raw.prijs3, 0),
    btw3:           safeBtw(raw.btw3),
    notities:       sanitize(raw.notities)
  }
}];

const body = $('Function: Input valideren en saniteren').first().json;
const customer = $('SQLite: Klant ophalen').first().json;
const counterRow = $('SQLite: Teller atomisch ophogen').first().json;

const prefix = 'NW';
const currentYear = new Date().getFullYear().toString();
const counter = parseInt(counterRow.invoice_counter || '1');

// Formatteer als NW-YYYY-NNNN
const paddedCounter = String(counter).padStart(4, '0');
const invoiceNumber = `${prefix}-${currentYear}-${paddedCounter}`;

// Haal company_email op uit instellingen
const companyRows = $('SQLite: Bedrijfsinstellingen ophalen').all().map(i => i.json);
const companyEmail = companyRows.find(r => r.key === 'company_email')?.value || 'info@mijnbedrijf.nl';

return [{
  json: {
    invoice_number: invoiceNumber,
    counter: counter,
    year: currentYear,
    customer: customer,
    body: body,
    company_email: companyEmail
  }
}];

const data = $input.first().json;
const body = data.body;
const today = new Date().toISOString().split('T')[0];
const paymentDays = 30;
const dueDate = new Date(Date.now() + paymentDays * 86400000).toISOString().split('T')[0];

const regels = [];
let subtotal = 0;
let btwTotaal = 0;

for (let i = 1; i <= 3; i++) {
  const omschrijving = body[`omschrijving${i}`] || '';
  if (!omschrijving) continue;

  const aantal = parseFloat(body[`aantal${i}`] || 1);
  const prijs = parseFloat(body[`prijs${i}`] || 0);
  const btwPct = parseFloat(body[`btw${i}`] || 21);

  const lineExcl = Math.round(aantal * prijs * 100) / 100;
  const btwBedrag = Math.round(lineExcl * btwPct / 100 * 100) / 100;
  const lineTotal = Math.round((lineExcl + btwBedrag) * 100) / 100;

  subtotal += lineExcl;
  btwTotaal += btwBedrag;

  regels.push({ omschrijving, aantal, prijs, btw_percentage: btwPct, btw_bedrag: btwBedrag, regel_totaal: lineTotal });
}

subtotal = Math.round(subtotal * 100) / 100;
btwTotaal = Math.round(btwTotaal * 100) / 100;
const total = Math.round((subtotal + btwTotaal) * 100) / 100;

return [{ json: { ...data, invoice_date: today, due_date: dueDate, regels, subtotal, btw_total: btwTotaal, total } }];

// Escape HTML entities om XSS te voorkomen in de gegenereerde PDF
function escHtml(str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const data = $input.first().json;
const customer = data.customer || {};
const regels = data.regels || [];

const regelRows = regels.map(r =>
  `<tr>
    <td>${escHtml(r.omschrijving)}</td>
    <td class="right">${r.aantal}</td>
    <td class="right">€ ${r.prijs.toFixed(2)}</td>
    <td class="right">${r.btw_percentage}%</td>
    <td class="right">€ ${r.btw_bedrag.toFixed(2)}</td>
    <td class="right">€ ${r.regel_totaal.toFixed(2)}</td>
  </tr>`
).join('');

const html = `<!DOCTYPE html>
<html lang="nl"><head><meta charset="UTF-8">
<style>@page{margin:15mm}body{font-family:Arial,sans-serif;font-size:10pt;color:#333}
