.ftr{margin-top:20px;font-size:8pt;color:#777;border-top:1px solid #ddd;padding-top:8px;text-align:center}</style>
</head><body>
<div class="hdr">
  <div class="co"><strong>{{company_name}}</strong><br>{{company_address}}<br>{{company_postcode}} {{company_city}}<br>KvK: {{company_kvk}}<br>BTW: {{company_btw}}</div>
  <div><h1>FACTUUR</h1><br><strong>Factuurnummer:</strong> ${escHtml(data.invoice_number)}<br><strong>Datum:</strong> ${escHtml(data.invoice_date)}<br><strong>Vervaldatum:</strong> ${escHtml(data.due_date)}</div>
</div>
<p><strong>Aan:</strong><br>${escHtml(customer.name)}<br>${escHtml(customer.address)}<br>${escHtml(customer.postcode)} ${escHtml(customer.city)}<br>${escHtml(customer.email)}</p>
<table><thead><tr><th>Omschrijving</th><th class="right">Aantal</th><th class="right">Stukprijs</th><th class="right">BTW%</th><th class="right">BTW</th><th class="right">Totaal</th></tr></thead><tbody>${regelRows}</tbody></table>
<table class="tot">
  <tr><td>Subtotaal excl. BTW</td><td class="right">€ ${data.subtotal.toFixed(2)}</td></tr>
  <tr><td>BTW totaal</td><td class="right">€ ${data.btw_total.toFixed(2)}</td></tr>
  <tr class="tot-row"><td><strong>TOTAAL incl. BTW</strong></td><td class="right"><strong>€ ${data.total.toFixed(2)}</strong></td></tr>
</table>
<div class="pay"><strong>Betaling:</strong> Gelieve binnen 30 dagen over te maken op<br>IBAN: {{company_iban}}<br>t.n.v. {{company_name}}<br>o.v.v. ${escHtml(data.invoice_number)}</div>
<div class="ftr">{{company_name}} | KvK: {{company_kvk}} | BTW: {{company_btw}} | {{company_email}} | IBAN: {{company_iban}}</div>
</body></html>`;

return [{ json: { ...data, html } }];

const data = $('Function: BTW berekenen en data samenvoegen').first().json;
const regels = data.regels || [];
// invoice_number is intern gegenereerd en bevat alleen [A-Z0-9-], geen extra escaping nodig
const invNum = data.invoice_number.replace(/'/g, "''");

// Bouw parameterized INSERT statements per regel (omschrijving reeds gesaneerd)
const queries = regels.map(r => {
  const desc = r.omschrijving.replace(/'/g, "''");
  return `INSERT INTO invoice_items (invoice_id, description, qty, unit_price, btw_percentage, btw_amount, line_total) ` +
    `SELECT id, '${desc}', ${r.aantal}, ${r.prijs}, ${r.btw_percentage}, ${r.btw_bedrag}, ${r.regel_totaal} ` +
    `FROM invoices WHERE invoice_number = '${invNum}'`;
});

return [{ json: { ...data, item_queries: queries } }];

